public class ReconciliationQueueable implements Queueable, Finalizer {
    private Integer batchIndex;
    public ReconciliationQueueable(Integer batchIndex) {
        this.batchIndex = batchIndex;
    }
    public void execute(QueueableContext context) {
        System.attachFinalizer(this);
        List<Reconciliation_Item__c> items = ReconciliationSelector.getBatch(batchIndex);
        ReconciliationDomain.process(items);
        if (ReconciliationSelector.hasMoreBatches(batchIndex)) {
            System.enqueueJob(new ReconciliationQueueable(batchIndex + 1));
        }
    }
    public void execute(FinalizerContext ctx) {
        if (ctx.getResult() == ParentJobResult.UNHANDLED_EXCEPTION) {
            ReconciliationBacklog.logFailedBatch(batchIndex, ctx.getException());
        }
    }
}

