public class ArchiveOldCasesBatch implements Database.Batchable<SObject>, Database.Stateful {
    public Integer archivedCount = 0;

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, CaseNumber, AccountId, ClosedDate, Subject, Description
            FROM Case
            WHERE IsClosed = true AND ClosedDate < :Date.today().addYears(-2)
        ]);
    }

    public void execute(Database.BatchableContext bc, List<Case> scope) {
        List<Case_Archive__b> archiveRecords = new List<Case_Archive__b>();
        for (Case c : scope) {
            archiveRecords.add(new Case_Archive__b(
                Case_Id__c = c.Id,
                Account_Id__c = c.AccountId,
                Closed_Date__c = c.ClosedDate,
                Subject__c = c.Subject
            ));
        }
        Database.insertImmediate(archiveRecords);
        archivedCount += scope.size();
    }

    public void finish(Database.BatchableContext bc) {
        ArchiveNotifier.notifyCompletion(archivedCount);
    }
}

