public class ExternalCreditCheckService {
    private static final Integer FAILURE_THRESHOLD = 5;
    private static final Integer COOLDOWN_SECONDS = 120;

    public static Boolean isCircuitOpen() {
        Circuit_Breaker_State__c state = CircuitBreakerSelector.getState('CreditCheckAPI');
        if (state.Is_Open__c && state.Opened_At__c.addSeconds(COOLDOWN_SECONDS) < System.now()) {
            state.Is_Open__c = false;
            state.Consecutive_Failures__c = 0;
            update state;
            return false;
        }
        return state.Is_Open__c;
    }

    public static HttpResponse callWithBreaker(HttpRequest req) {
        if (isCircuitOpen()) {
            throw new CalloutException('Credit check circuit open - skipping call, using fallback');
        }
        try {
            HttpResponse res = new Http().send(req);
            CircuitBreakerSelector.recordSuccess('CreditCheckAPI');
            return res;
        } catch (CalloutException e) {
            CircuitBreakerSelector.recordFailure('CreditCheckAPI', FAILURE_THRESHOLD);
            throw e;
        }
    }
}

